<script setup lang="ts">
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { useApp } from '../stores/app'
import { nextPublication,dateLabel } from '../lib/format'
import Icon from '../components/Icon.vue'
const app=useApp(),router=useRouter(),settings=ref({...app.settings}),busy=ref(false)
async function logout(){try{await app.logout();await router.replace('/login')}catch(e){app.notify(app.errorMessage(e))}}
async function save(){busy.value=true;try{await app.saveSettings(settings.value)}catch(e){app.notify(app.errorMessage(e))}finally{busy.value=false}}
async function unfollow(kind:'category'|'source'|'keyword',value:string){try{await app.toggleFollow(kind,value)}catch{}}
</script>
<template><div class="page account-page"><div class="page-heading"><div><div class="eyebrow">YOUR OWN LITTLE UNIVERSE</div><h1>我的空间<span class="orange">。</span></h1><p>管理你的兴趣、阅读习惯和私人空间。</p></div><span class="private-pill"><Icon name="LockKeyhole" :size="13"/>仅你可见</span></div><div class="account-grid"><section class="form-card profile-card"><span class="profile-avatar">Y<span>✳</span></span><h2>{{app.demo?'好奇心研究员':'私人空间所有者'}}</h2><p>{{app.demo?'演示模式 · 所有互动只保存在本机':app.user?.email}}</p><div class="profile-stats"><span><strong>{{app.read.length}}</strong>阅读足迹</span><span><strong>{{app.bookmarks.length}}</strong>收藏</span><span><strong>{{app.notes.length}}</strong>私人笔记</span></div><button class="btn outline" @click="logout"><Icon name="LogOut" :size="16"/>{{app.demo?'退出演示，返回登录':'安全退出所有设备会话'}}</button><small>退出后，当前页面中的私人内容会立即清空。</small></section><section class="form-card"><h3><Icon name="Clock3" :size="18"/>每日节奏</h3><form @submit.prevent="save"><label>发布时区<select v-model="settings.timezone"><option>Asia/Tokyo</option><option>Asia/Shanghai</option></select></label><label>每日最多条数<input v-model.number="settings.daily_target" type="number" min="1" max="50" required/></label><label class="switch-label"><span><strong>自动新闻 Agent</strong><small>允许后台采集与制稿</small></span><input v-model="settings.agent_enabled" type="checkbox" role="switch"/></label><label class="switch-label"><span><strong>每日 08:00 自动发布</strong><small>仅发布已通过核验的排队内容</small></span><input v-model="settings.auto_publish" type="checkbox" role="switch"/></label><p class="form-hint">下次计划：{{dateLabel(nextPublication(settings.timezone).toISOString(),settings.timezone)}}（{{settings.timezone}}）。实际触发可能延迟。</p><button class="btn primary small" :disabled="busy">保存设置<Icon name="Check" :size="16"/></button></form></section><section class="form-card interests-card"><h3><Icon name="Rss" :size="18"/>我关注的线索</h3><div v-if="app.follows.length" class="follow-list"><div v-for="f in app.follows" :key="f.kind+f.value"><span><small>{{{category:'分类',source:'来源',keyword:'关键词'}[f.kind]}}</small>{{f.value}}</span><button class="icon-btn" aria-label="取消关注" @click="unfollow(f.kind,f.value)"><Icon name="X" :size="16"/></button></div></div><p v-else class="muted">还没有关注的主题。在发现页选一个喜欢的分类吧。</p><RouterLink to="/discover" class="source-link">探索我的兴趣<Icon name="ArrowUpRight" :size="16"/></RouterLink></section><section class="form-card privacy-card"><h3><Icon name="ShieldCheck" :size="18"/>为私人阅读而设计</h3><p>{{app.demo?'当前处于公开演示体验，示例不是实时新闻；收藏、笔记和手记仅存于当前浏览器。连接 Supabase 后，真实内容将通过所有者权限进行保护。':'新闻和笔记由数据库 RLS 保护，图片存放于私有存储。临时图片链接有效期为 5 分钟，分享后也需所有者登录才能读取正文。'}}</p><RouterLink to="/admin" class="source-link">进入新闻管理后台<Icon name="ArrowUpRight" :size="16"/></RouterLink></section></div></div></template>
